#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <iostream>
using namespace fedspatial;static bool ld(const std::string&n,Matrix*x){return read_matrix("sync_gpu/tests/fixtures/sync_gpu/"+n,x);}int main(){Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sg(2,2);double a[]={0,0,1,.2,.3,1.1},b[]={0,0,1.5,1.5},q[]={1.2,-.4,.7};std::copy(a,a+6,s.a.begin());std::copy(b,b+4,k.a.begin());std::copy(q,q+3,z.a.begin());for(double&v:x.a)v=1;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sg(0,0)=.7;sg(1,1)=.4;sg(0,1)=sg(1,0)=.05;GpuContext c(0);double e[9]={},sy=0;const char* names[]={"DD","DA","DR","AD","AA","AR","RD","RA","RR"};for(int i=0;i<7;i++){Matrix p;if(!ld("DELTA_THETA_POINT"+std::to_string(i)+"_PARAM.txt",&p))return 2;auto h=compute_m_second_derivatives(c,{s,z,x},k,{g,mu,sg,p(0,0),p(1,0),p(2,0)});Matrix vals[]={h.dd,h.da,h.dr,h.ad,h.aa,h.ar,h.rd,h.ra,h.rr};for(int j=0;j<9;j++){Matrix r;if(!ld("DELTA_THETA_POINT"+std::to_string(i)+"_M_HESS_"+names[j]+".txt",&r))return 2;e[j]=std::max(e[j],max_abs_diff(vals[j],r));}sy=std::max({sy,max_abs_diff(h.da,h.ad),max_abs_diff(h.dr,h.rd),max_abs_diff(h.ar,h.ra)});}double mx=0;for(double v:e)mx=std::max(mx,v);std::cout<<"M_HESS_DD_MAX_ABS_ERROR="<<e[0]<<"\nM_HESS_DA_MAX_ABS_ERROR="<<e[1]<<"\nM_HESS_DR_MAX_ABS_ERROR="<<e[2]<<"\nM_HESS_AD_MAX_ABS_ERROR="<<e[3]<<"\nM_HESS_AA_MAX_ABS_ERROR="<<e[4]<<"\nM_HESS_AR_MAX_ABS_ERROR="<<e[5]<<"\nM_HESS_RD_MAX_ABS_ERROR="<<e[6]<<"\nM_HESS_RA_MAX_ABS_ERROR="<<e[7]<<"\nM_HESS_RR_MAX_ABS_ERROR="<<e[8]<<"\nM_HESS_MAX_ABS_ERROR="<<mx<<"\nM_HESS_SYMMETRY_MAX_ABS_ERROR="<<sy<<"\nM_HESS_PARITY="<<(mx<=1e-10?"PASS":"FAIL")<<"\n";return mx<=1e-10?0:1;}
